import os
import json
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _read_file_bytes(path: str) -> bytes:
    with open(path, "rb") as f:
        return f.read()


def _clean_value(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, str):
        return value.strip()
    return value


def _extract_amount_from_field(field: Any) -> Optional[float]:
    if field is None:
        return None
    for attr in ("value_number", "value", "content"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                try:
                    return float(v)
                except Exception:
                    pass
    if isinstance(field, (int, float)):
        return float(field)
    if isinstance(field, str):
        try:
            return float(field.replace(",", "").strip())
        except Exception:
            return None
    return None


def _extract_items(result: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    line_items = getattr(result, "documents", None) or []
    for doc in line_items:
        fields = getattr(doc, "fields", {}) or {}
        for key in ("Items", "LineItems", "line_items"):
            if key in fields and fields[key]:
                value = fields[key]
                entries = getattr(value, "value_array", None) or getattr(value, "value", None) or []
                for entry in entries:
                    entry_fields = getattr(entry, "value_object", None) or getattr(entry, "fields", None) or {}
                    item: Dict[str, Any] = {}
                    for k, field in entry_fields.items():
                        if hasattr(field, "content"):
                            item[k] = _clean_value(getattr(field, "content"))
                        elif hasattr(field, "value_string"):
                            item[k] = _clean_value(getattr(field, "value_string"))
                        elif hasattr(field, "value_number"):
                            item[k] = _clean_value(getattr(field, "value_number"))
                        elif hasattr(field, "value_integer"):
                            item[k] = _clean_value(getattr(field, "value_integer"))
                        elif hasattr(field, "value_currency"):
                            currency = getattr(field, "value_currency")
                            item[k] = {
                                "amount": _extract_amount_from_field(currency),
                                "code": getattr(currency, "code", None),
                            }
                        else:
                            item[k] = _clean_value(field)
                    items.append(item)
                return items
    return items


def extract_receipt_document(file_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            analyze_request=f,
            content_type="application/octet-stream",
        )
    result = poller.result()

    merchant = None
    tax = None
    total = None
    items = _extract_items(result)

    documents = getattr(result, "documents", None) or []
    if documents:
        fields = getattr(documents[0], "fields", {}) or {}

        merchant_field = (
            fields.get("VendorName")
            or fields.get("MerchantName")
            or fields.get("SellerName")
            or fields.get("merchant")
        )
        if merchant_field is not None:
            merchant = getattr(merchant_field, "content", None) or getattr(merchant_field, "value", None)

        tax_field = fields.get("TotalTax") or fields.get("Tax") or fields.get("tax")
        if tax_field is not None:
            tax = _extract_amount_from_field(getattr(tax_field, "value_currency", tax_field)) or _extract_amount_from_field(tax_field)

        total_field = fields.get("InvoiceTotal") or fields.get("Total") or fields.get("total")
        if total_field is not None:
            total = _extract_amount_from_field(getattr(total_field, "value_currency", total_field)) or _extract_amount_from_field(total_field)

    return {
        "merchant": _clean_value(merchant),
        "tax": tax,
        "total": total,
        "items": items,
    }
